import { useEffect, useMemo, useState } from 'react';
import { PRODUCTS, CATEGORIES, type Product } from './data/products';
import Header from './components/Header';
import Home from './components/Home';
import ProductGrid from './components/ProductGrid';
import ProductDetail from './components/ProductDetail';
import CartDrawer from './components/CartDrawer';
import Checkout from './components/Checkout';
import OrderSuccess from './components/OrderSuccess';
import Toast, { type ToastMsg } from './components/Toast';

type AtomsStorage = {
  get: <T>(key: string, fallback: T) => T;
  set: (key: string, value: unknown) => void;
  remove: (key: string) => void;
  flush?: () => Promise<void>;
};

function storage(): AtomsStorage | undefined {
  const w = window as unknown as { atoms?: { storage?: AtomsStorage } };
  return w.atoms?.storage;
}

export type View =
  | { name: 'home' }
  | { name: 'list'; category: string }
  | { name: 'detail'; id: string }
  | { name: 'checkout' }
  | { name: 'success'; order: OrderSummary };

export type CartLine = { id: string; qty: number };
export type OrderSummary = {
  orderNo: string;
  items: { name: string; qty: number; price: number }[];
  subtotal: number;
  shipping: number;
  total: number;
  name: string;
  phone: string;
  address: string;
  pay: string;
  placedAt: string;
};

const CART_KEY = 'shiguang.cart.v1';
const ORDER_KEY = 'shiguang.order.v1';
const FREE_SHIPPING = 199;
const SHIPPING_FEE = 12;

function shippingFor(subtotal: number): number {
  if (subtotal === 0) return 0;
  return subtotal >= FREE_SHIPPING ? 0 : SHIPPING_FEE;
}

function readCart(): CartLine[] {
  try {
    const store = storage();
    const raw = store?.get(CART_KEY, [] as CartLine[]);
    if (Array.isArray(raw)) {
      return raw
        .filter(
          (l): l is CartLine =>
            !!l && typeof l.id === 'string' && typeof l.qty === 'number' && l.qty > 0,
        )
        .map((l) => ({ id: l.id, qty: Math.min(99, Math.floor(l.qty)) }));
    }
  } catch {
    /* storage unavailable */
  }
  return [];
}

function readOrder(): OrderSummary | null {
  try {
    const store = storage();
    const raw = store?.get(ORDER_KEY, null as OrderSummary | null);
    if (raw && typeof raw === 'object' && typeof raw.orderNo === 'string') {
      return raw as OrderSummary;
    }
  } catch {
    /* storage unavailable */
  }
  return null;
}

export default function App() {
  const [view, setView] = useState<View>({ name: 'home' });
  const [cart, setCart] = useState<CartLine[]>(() => readCart());
  const [cartOpen, setCartOpen] = useState(false);
  const [toast, setToast] = useState<ToastMsg | null>(null);
  const [bump, setBump] = useState(0);
  const [query, setQuery] = useState('');
  const [lastOrder, setLastOrder] = useState<OrderSummary | null>(() => readOrder());

  const count = cart.reduce((s, l) => s + l.qty, 0);

  const cartDetailed = useMemo(() => {
    return cart
      .map((l) => {
        const p = PRODUCTS.find((x) => x.id === l.id);
        return p ? { product: p, qty: l.qty } : null;
      })
      .filter((x): x is { product: Product; qty: number } => x !== null);
  }, [cart]);

  const subtotal = cartDetailed.reduce((s, l) => s + l.product.price * l.qty, 0);
  const shipping = shippingFor(subtotal);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    if (!cartOpen) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') setCartOpen(false);
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [cartOpen]);

  async function persistCart(next: CartLine[]) {
    setCart(next);
    try {
      const store = storage();
      store?.set(CART_KEY, next);
      await store?.flush?.();
    } catch {
      /* keep in-memory state */
    }
  }

  function addToCart(id: string, qty: number) {
    const existing = cart.find((l) => l.id === id);
    const next = existing
      ? cart.map((l) => (l.id === id ? { ...l, qty: Math.min(99, l.qty + qty) } : l))
      : [...cart, { id, qty: Math.min(99, Math.max(1, qty)) }];
    void persistCart(next);
    const p = PRODUCTS.find((x) => x.id === id);
    setBump((b) => b + 1);
    setToast({ text: p ? `已加入购物车：${p.name} × ${qty}` : '已加入购物车' });
  }

  function setQty(id: string, qty: number) {
    if (qty <= 0) {
      removeLine(id);
      return;
    }
    void persistCart(cart.map((l) => (l.id === id ? { ...l, qty: Math.min(99, qty) } : l)));
  }

  function removeLine(id: string) {
    void persistCart(cart.filter((l) => l.id !== id));
  }

  async function placeOrder(data: { name: string; phone: string; address: string; pay: string }) {
    const order: OrderSummary = {
      orderNo: 'SG' + String(Date.now()).slice(-8),
      items: cartDetailed.map((l) => ({ name: l.product.name, qty: l.qty, price: l.product.price })),
      subtotal,
      shipping,
      total: subtotal + shipping,
      name: data.name,
      phone: data.phone,
      address: data.address,
      pay: data.pay,
      placedAt: new Date().toLocaleString('zh-CN', { hour12: false }),
    };
    setLastOrder(order);
    setCart([]);
    try {
      const store = storage();
      store?.set(ORDER_KEY, order);
      store?.set(CART_KEY, []);
      await store?.flush?.();
    } catch {
      /* ignore */
    }
    setCartOpen(false);
    setView({ name: 'success', order });
    window.scrollTo({ top: 0, behavior: 'auto' });
  }

  function go(next: View) {
    setView(next);
    setCartOpen(false);
    window.scrollTo({ top: 0, behavior: 'auto' });
  }

  function openCategory(cat: string) {
    setQuery('');
    go({ name: 'list', category: cat });
  }

  function onHeaderQuery(q: string) {
    setQuery(q);
    if (view.name !== 'list') setView({ name: 'list', category: '全部' });
  }

  const activeCategory = view.name === 'list' ? view.category : '全部';

  return (
    <div className="app">
      <a className="skip-link" href="#main">跳到主要内容</a>
      <Header
        count={count}
        bump={bump}
        query={query}
        activeCategory={view.name === 'list' ? activeCategory : ''}
        categories={CATEGORIES}
        onQuery={onHeaderQuery}
        onSubmitSearch={() => {
          if (view.name !== 'list') go({ name: 'list', category: '全部' });
        }}
        onHome={() => go({ name: 'home' })}
        onCart={() => setCartOpen(true)}
        onCategory={openCategory}
      />

      <main id="main">
        {view.name === 'home' && (
          <Home
            products={PRODUCTS}
            categories={CATEGORIES}
            onCategory={openCategory}
            onProduct={(id) => go({ name: 'detail', id })}
            onShopAll={() => go({ name: 'list', category: '全部' })}
            onQuickAdd={(id) => addToCart(id, 1)}
          />
        )}

        {view.name === 'list' && (
          <ProductGrid
            products={PRODUCTS}
            categories={CATEGORIES}
            activeCategory={view.category}
            query={query}
            onQuery={setQuery}
            onCategory={(c) => {
              setQuery('');
              setView({ name: 'list', category: c });
              window.scrollTo({ top: 0, behavior: 'auto' });
            }}
            onProduct={(id) => go({ name: 'detail', id })}
            onAdd={(id) => addToCart(id, 1)}
            onClear={() => {
              setQuery('');
              setView({ name: 'list', category: '全部' });
            }}
          />
        )}

        {view.name === 'detail' && (
          <ProductDetail
            key={view.id}
            product={PRODUCTS.find((p) => p.id === view.id)}
            onBack={() => go({ name: 'list', category: '全部' })}
            onAdd={(id, qty) => addToCart(id, qty)}
            onOpenCart={() => setCartOpen(true)}
          />
        )}

        {view.name === 'checkout' && (
          <Checkout
            items={cartDetailed}
            subtotal={subtotal}
            shipping={shipping}
            freeShipping={FREE_SHIPPING}
            onBack={() => setCartOpen(true)}
            onShop={() => go({ name: 'list', category: '全部' })}
            onSubmit={placeOrder}
          />
        )}

        {view.name === 'success' && (
          <OrderSuccess order={view.order} onHome={() => go({ name: 'home' })} onShop={() => go({ name: 'list', category: '全部' })} />
        )}
      </main>

      <footer className="site-footer">
        <div className="footer-inner">
          <div>
            <p className="footer-brand">拾光集</p>
            <p className="footer-note">日常器物选品 · 站内商品、价格与流程均为演示数据</p>
          </div>
          <div className="footer-links">
            <button onClick={() => openCategory('全部')}>全部商品</button>
            <button onClick={() => setCartOpen(true)}>查看购物车</button>
            {lastOrder && (
              <button onClick={() => go({ name: 'success', order: lastOrder })}>
                查看上次订单 {lastOrder.orderNo}
              </button>
            )}
          </div>
        </div>
        <p className="footer-legal">本站为演示站点，不接入支付与物流，下单不会产生实际交易。</p>
      </footer>

      <CartDrawer
        open={cartOpen}
        items={cartDetailed}
        subtotal={subtotal}
        shipping={shipping}
        onClose={() => setCartOpen(false)}
        onQty={setQty}
        onRemove={removeLine}
        onCheckout={() => {
          setCartOpen(false);
          go({ name: 'checkout' });
        }}
        onShop={() => {
          setCartOpen(false);
          go({ name: 'list', category: '全部' });
        }}
      />

      <Toast toast={toast} />
    </div>
  );
}

