*,*::before,*::after{box-sizing:border-box}

:root{
  --paper:#f5efe5;
  --paper-2:#fdfaf4;
  --ink:#221d17;
  --ink-soft:#6b6156;
  --amber:#d4761b;
  --amber-deep:#a9590c;
  --amber-tint:#fbe7cd;
  --sage:#5b7a63;
  --line:#e4d9c7;
  --danger:#b1352a;
  --radius:14px;
  --shadow:0 18px 40px -26px rgba(34,29,23,.55);
  --font-head:'Trebuchet MS','PingFang SC','Hiragino Sans GB','Microsoft YaHei',system-ui,sans-serif;
  --font-body:'PingFang SC','Hiragino Sans GB','Microsoft YaHei',system-ui,sans-serif;
}

html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--paper);
  color:var(--ink);
  font-family:var(--font-body);
  font-size:16px;
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
button{font-family:inherit;cursor:pointer;color:inherit}
img,svg{display:block;max-width:100%}
:focus-visible{outline:3px solid var(--amber);outline-offset:2px;border-radius:4px}

.skip-link{
  position:absolute;left:12px;top:-52px;z-index:200;
  background:var(--ink);color:#fff;padding:10px 16px;border-radius:0 0 10px 10px;
  text-decoration:none;font-size:14px;transition:top .18s ease;
}
.skip-link:focus{top:0}

.app{min-height:100vh;display:flex;flex-direction:column}
#main{flex:1}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:60;
  background:rgba(253,250,244,.95);
  backdrop-filter:blur(10px);
  border-bottom:1px solid var(--line);
}
.header-inner{
  max-width:1180px;margin:0 auto;padding:12px 22px;
  display:flex;align-items:center;gap:18px;
}
.brand{
  display:flex;align-items:center;gap:10px;
  background:none;border:0;padding:0;
  font-family:var(--font-head);
  font-size:23px;font-weight:800;letter-spacing:.04em;
  color:var(--ink);
}
.brand-dot{
  width:14px;height:14px;border-radius:50%;
  background:var(--amber);
  box-shadow:0 0 0 4px var(--amber-tint);
  flex-shrink:0;
}
.brand-text{display:flex;flex-direction:column;line-height:1.1;text-align:left}
.brand-text small{font-size:10px;font-weight:500;letter-spacing:.2em;color:var(--ink-soft);margin-top:3px}

.header-search{
  flex:1;min-width:0;
  display:flex;align-items:center;
  background:#fff;
  border:1px solid var(--line);
  border-radius:999px;
  padding:0 6px 0 16px;
  max-width:430px;
}
.header-search:focus-within{border-color:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)}
.header-search input{
  flex:1;border:0;background:none;padding:10px 0;font-size:15px;color:var(--ink);
  font-family:inherit;min-width:0;
}
.header-search input:focus{outline:none}
.search-btn{
  border:0;background:var(--ink);color:#fff;
  border-radius:999px;padding:7px 15px;font-size:14px;font-weight:600;
  white-space:nowrap;
}
.search-btn:hover{background:#3a322a}

.header-actions{display:flex;align-items:center;gap:10px;margin-left:auto}
.cart-btn{
  position:relative;
  display:inline-flex;align-items:center;gap:8px;
  background:var(--ink);color:#fff;
  border:0;border-radius:999px;
  padding:9px 16px 9px 14px;font-size:14px;font-weight:600;
}
.cart-btn:hover{background:#3a322a}
.cart-badge{
  position:absolute;top:-7px;right:-6px;
  min-width:22px;height:22px;padding:0 6px;
  display:grid;place-items:center;
  background:var(--amber);color:#fff;
  border-radius:999px;font-size:12px;font-weight:700;
  border:2px solid var(--paper-2);
}
.cart-badge.bump{animation:bump .5s ease}
@keyframes bump{
  0%{transform:scale(1)}
  35%{transform:scale(1.5)}
  70%{transform:scale(.9)}
  100%{transform:scale(1)}
}

.cat-nav{
  border-top:1px solid var(--line);
  background:rgba(245,239,229,.9);
  overflow-x:auto;scrollbar-width:thin;
}
.cat-nav-inner{
  max-width:1180px;margin:0 auto;padding:0 22px;
  display:flex;gap:4px;
}
.cat-nav button{
  background:none;border:0;padding:10px 12px;
  font-size:14px;color:var(--ink-soft);white-space:nowrap;
  border-bottom:2px solid transparent;
}
.cat-nav button:hover{color:var(--ink)}
.cat-nav button.active{color:var(--amber-deep);border-bottom-color:var(--amber);font-weight:700}

/* ---------- Hero ---------- */
.hero{
  max-width:1180px;margin:0 auto;padding:40px 22px 12px;
  display:grid;grid-template-columns:1.05fr .95fr;gap:38px;align-items:center;
}
.hero-copy h1{
  font-family:var(--font-head);
  font-size:clamp(34px,4.6vw,58px);
  line-height:1.06;letter-spacing:-.025em;
  margin:0 0 18px;font-weight:800;
}
.hero-copy h1 span{display:block}
.hero-copy h1 em{font-style:normal;color:var(--amber-deep)}
.hero-kicker{
  display:inline-block;margin-bottom:16px;
  background:var(--amber-tint);color:var(--amber-deep);
  border-radius:999px;padding:5px 14px;font-size:13px;font-weight:600;
}
.hero-copy p{font-size:17px;color:var(--ink-soft);max-width:44ch;margin:0 0 26px}
.hero-cta{display:flex;gap:12px;flex-wrap:wrap}

.btn-primary{
  background:var(--amber);color:#fff;border:0;
  border-radius:999px;padding:13px 26px;
  font-size:15px;font-weight:700;
  transition:background .18s ease,transform .18s ease,box-shadow .18s ease;
}
.btn-primary:hover{background:var(--amber-deep);transform:translateY(-1px);box-shadow:0 10px 22px -14px rgba(169,89,12,.9)}
.btn-primary:active{transform:translateY(0)}
.btn-ghost{
  background:transparent;color:var(--ink);
  border:1.5px solid var(--ink);border-radius:999px;
  padding:13px 24px;font-size:15px;font-weight:600;
  transition:background .18s ease;
}
.btn-ghost:hover{background:#efe6d8}

.hero-art{position:relative;aspect-ratio:1/1;max-width:460px;justify-self:end;width:100%}
.art-tile{
  position:absolute;border-radius:18px;overflow:hidden;
  box-shadow:var(--shadow);
  border:1px solid rgba(255,255,255,.65);
  cursor:pointer;transition:transform .3s ease;
  padding:0;background:none;
}
.art-tile:hover{transform:translateY(-5px)}
.art-tile .tile-label{
  position:absolute;left:0;right:0;bottom:0;
  padding:8px 12px;background:linear-gradient(transparent,rgba(20,16,12,.66));
  color:#fff;font-size:13px;font-weight:600;text-align:left;
}
.art-1{width:56%;height:62%;left:0;top:0;z-index:2}
.art-2{width:40%;height:44%;right:0;top:6%;z-index:1}
.art-3{width:50%;height:40%;right:2%;bottom:0;z-index:3}
.art-disc{
  position:absolute;left:4%;bottom:6%;
  width:34%;aspect-ratio:1/1;border-radius:50%;
  background:repeating-radial-gradient(circle at 50% 50%,var(--amber-tint) 0 8px,#f2e0c8 8px 16px);
  border:1px solid var(--line);
  display:grid;place-items:center;text-align:center;
  font-size:12px;font-weight:700;color:var(--amber-deep);line-height:1.35;
  z-index:4;
}

/* ---------- Sections ---------- */
.section{max-width:1180px;margin:0 auto;padding:44px 22px}
.section-head{
  display:flex;align-items:flex-end;justify-content:space-between;
  gap:16px;flex-wrap:wrap;margin-bottom:22px;
}
.section-head h2{
  font-family:var(--font-head);
  font-size:clamp(22px,2.6vw,30px);
  margin:0;letter-spacing:-.015em;font-weight:800;
}
.section-head p{margin:6px 0 0;color:var(--ink-soft);font-size:15px}
.link-btn{
  background:none;border:0;padding:4px 0;
  color:var(--amber-deep);font-weight:600;font-size:15px;
  border-bottom:1.5px solid transparent;
}
.link-btn:hover{border-bottom-color:var(--amber)}

/* Category rail */
.cat-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}
.cat-card{
  background:var(--paper-2);
  border:1px solid var(--line);border-radius:var(--radius);
  padding:18px 14px;text-align:left;
  display:flex;flex-direction:column;gap:6px;
  transition:transform .18s ease,border-color .18s ease,background .18s ease;
}
.cat-card:hover{transform:translateY(-3px);border-color:var(--amber);background:#fffdf9}
.cat-icon{
  width:40px;height:40px;border-radius:12px;
  display:grid;place-items:center;font-size:19px;
  background:var(--amber-tint);margin-bottom:2px;
}
.cat-card strong{font-size:15px}
.cat-card span{font-size:12.5px;color:var(--ink-soft)}

/* ---------- Product cards ---------- */
.product-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(232px,1fr));
  gap:20px;
}
.product-card{
  background:var(--paper-2);
  border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;display:flex;flex-direction:column;
  transition:box-shadow .2s ease,transform .2s ease,border-color .2s ease;
}
.product-card:hover{box-shadow:var(--shadow);transform:translateY(-3px);border-color:#d8c8ae}
.card-media-wrap{position:relative;overflow:hidden}
.card-media{
  position:relative;aspect-ratio:4/3;overflow:hidden;cursor:pointer;
  border:0;padding:0;background:none;display:block;width:100%;
}
.card-media .cover{transition:transform .45s ease}
.product-card:hover .card-media .cover{transform:scale(1.06)}
.card-tag{
  position:absolute;top:10px;left:10px;z-index:2;
  background:rgba(253,250,244,.94);color:var(--amber-deep);
  font-size:11.5px;font-weight:700;padding:3px 9px;border-radius:999px;
}
.quick-add{
  position:absolute;left:10px;right:10px;bottom:10px;z-index:2;
  background:rgba(34,29,23,.94);color:#fff;border:0;
  border-radius:10px;padding:9px;font-size:13.5px;font-weight:600;
  opacity:0;transform:translateY(8px);
  transition:opacity .2s ease,transform .2s ease,background .2s ease;
}
.product-card:hover .quick-add,.product-card:focus-within .quick-add{opacity:1;transform:translateY(0)}
.quick-add:hover{background:var(--amber-deep)}
.card-body{padding:14px 15px 16px;display:flex;flex-direction:column;gap:6px;flex:1}
.card-cat{font-size:12px;color:var(--sage);font-weight:700}
.card-name{
  font-size:15.5px;font-weight:600;line-height:1.4;margin:0;
  background:none;border:0;padding:0;text-align:left;color:var(--ink);
}
.card-name:hover{color:var(--amber-deep)}
.card-price-row{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:6px}
.price{font-family:var(--font-head);font-size:18px;font-weight:800;color:var(--amber-deep);white-space:nowrap}
.price small{font-size:12px;font-weight:700;margin-right:1px}
.stock{font-size:12px;color:var(--ink-soft)}

/* ---------- List page ---------- */
.list-head{max-width:1180px;margin:0 auto;padding:36px 22px 0}
.list-head h1{font-family:var(--font-head);font-size:clamp(26px,3.2vw,38px);margin:0 0 4px;font-weight:800;letter-spacing:-.015em}
.list-head p{margin:0;color:var(--ink-soft)}
.filter-bar{
  max-width:1180px;margin:18px auto 0;padding:0 22px;
  display:flex;gap:10px;flex-wrap:wrap;align-items:center;
}
.chip{
  background:var(--paper-2);border:1px solid var(--line);
  border-radius:999px;padding:7px 15px;font-size:14px;color:var(--ink-soft);
  transition:background .15s ease,color .15s ease,border-color .15s ease;
}
.chip:hover{border-color:var(--amber);color:var(--ink)}
.chip.active{background:var(--ink);border-color:var(--ink);color:#fff;font-weight:600}
.filter-search{
  margin-left:auto;display:flex;align-items:center;gap:8px;
  background:#fff;border:1px solid var(--line);border-radius:999px;padding:0 6px 0 14px;
  min-width:230px;flex:1;max-width:340px;
}
