type Props = {
  count: number;
  bump: number;
  query: string;
  activeCategory: string;
  categories: string[];
  onQuery: (v: string) => void;
  onSubmitSearch: () => void;
  onHome: () => void;
  onCart: () => void;
  onCategory: (c: string) => void;
};

export default function Header({
  count,
  bump,
  query,
  activeCategory,
  categories,
  onQuery,
  onSubmitSearch,
  onHome,
  onCart,
  onCategory,
}: Props) {
  return (
    <header className="site-header">
      <div className="header-inner">
        <button className="brand" onClick={onHome} aria-label="拾光集 首页">
          <span className="brand-dot" aria-hidden="true" />
          <span className="brand-text">
            拾光集
            <small>SHIGUANG SELECT</small>
          </span>
        </button>

        <form
          className="header-search"
          role="search"
          onSubmit={(e) => {
            e.preventDefault();
            onSubmitSearch();
          }}
        >
          <input
            type="search"
            value={query}
            onChange={(e) => onQuery(e.target.value)}
            placeholder="搜索杯壶、蜡烛、文具…"
            aria-label="搜索商品"
          />
          <button type="submit" className="search-btn">搜索</button>
        </form>

        <div className="header-actions">
          <button className="cart-btn" onClick={onCart} aria-label={`打开购物车，共 ${count} 件商品`}>
            <span aria-hidden="true">🛒</span>
            <span className="cart-label">购物车</span>
            <span key={bump} className={`cart-badge${bump ? ' bump' : ''}`}>{count}</span>
          </button>
        </div>
      </div>

      <nav className="cat-nav" aria-label="商品分类">
        <div className="cat-nav-inner">
          {categories.map((c) => (
            <button
              key={c}
              className={c === activeCategory ? 'active' : ''}
              onClick={() => onCategory(c)}
              aria-current={c === activeCategory ? 'page' : undefined}
            >
              {c}
            </button>
          ))}
        </div>
      </nav>
    </header>
  );
}

