type Props = {
  colors: [string, string];
  glyph: string;
  label: string;
};

/** Locally generated cover art: layered gradient + glyph, no external images. */
export default function ProductCover({ colors, glyph, label }: Props) {
  const [a, b] = colors;
  const gid = 'g' + label.replace(/[^a-zA-Z0-9]/g, '') + a.replace('#', '');
  return (
    <svg
      className="cover"
      viewBox="0 0 200 200"
      role="img"
      aria-label={`${label} 示意图`}
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0.85" y2="1">
          <stop offset="0%" stopColor={a} />
          <stop offset="100%" stopColor={b} />
        </linearGradient>
      </defs>
      <rect width="200" height="200" fill={`url(#${gid})`} />
      <circle cx="152" cy="48" r="46" fill="#ffffff" opacity="0.22" />
      <path d="M0 148 Q 60 118 104 146 T 200 132 L 200 200 L 0 200 Z" fill="#ffffff" opacity="0.18" />
      <path d="M0 168 Q 54 146 108 166 T 200 158 L 200 200 L 0 200 Z" fill="#1d1814" opacity="0.08" />
      <text x="100" y="104" textAnchor="middle" dominantBaseline="central" fontSize="62">
        {glyph}
      </text>
    </svg>
  );
}

