import { useMemo } from 'react';
import type { Product } from '../data/products';
import ProductCard from './ProductCard';

type Props = {
  products: Product[];
  categories: string[];
  activeCategory: string;
  query: string;
  onQuery: (v: string) => void;
  onCategory: (c: string) => void;
  onProduct: (id: string) => void;
  onAdd: (id: string) => void;
  onClear: () => void;
};

export default function ProductGrid({
  products,
  categories,
  activeCategory,
  query,
  onQuery,
  onCategory,
  onProduct,
  onAdd,
  onClear,
}: Props) {
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return products.filter((p) => {
      const inCat = activeCategory === '全部' || p.category === activeCategory;
      const hit =
        !q ||
        p.name.toLowerCase().includes(q) ||
        p.desc.toLowerCase().includes(q) ||
        p.category.toLowerCase().includes(q);
      return inCat && hit;
    });
  }, [products, activeCategory, query]);

  const heading = activeCategory === '全部' ? '全部商品' : activeCategory;

  return (
    <section aria-labelledby="list-title">
      <div className="list-head">
        <h1 id="list-title">{heading}</h1>
        <p>示例商品目录，价格与库存仅用于演示筛选与下单流程。</p>
      </div>

      <div className="filter-bar">
        {categories.map((c) => (
          <button
            key={c}
            className={`chip${c === activeCategory ? ' active' : ''}`}
            onClick={() => onCategory(c)}
            aria-pressed={c === activeCategory}
          >
            {c}
          </button>
        ))}
        <div className="filter-search">
          <input
            type="search"
            value={query}
            onChange={(e) => onQuery(e.target.value)}
            placeholder="商品名或关键词"
            aria-label="在列表中搜索商品"
          />
          {(query || activeCategory !== '全部') && (
            <button className="filter-clear" onClick={onClear}>清除筛选</button>
          )}
        </div>
      </div>

      <p className="result-note" aria-live="polite">
        共 {filtered.length} 件商品{query.trim() ? `，匹配“${query.trim()}”` : ''}。
      </p>

      <div className="section" style={{ paddingTop: 18 }}>
        {filtered.length === 0 ? (
          <div className="empty">
            <div className="empty-symbol" aria-hidden="true">🔍</div>
            <h3>没有找到相符的商品</h3>
            <p>试试换一个关键词，或者回到全部商品看看。</p>
            <button className="btn-primary" onClick={onClear}>查看全部商品</button>
          </div>
        ) : (
          <div className="product-grid">
            {filtered.map((p) => (
              <ProductCard key={p.id} product={p} onOpen={onProduct} onAdd={onAdd} />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

