import { useState } from 'react';
import type { Product } from '../data/products';

type Line = { product: Product; qty: number };

type Props = {
  items: Line[];
  subtotal: number;
  shipping: number;
  freeShipping: number;
  onBack: () => void;
  onShop: () => void;
  onSubmit: (data: { name: string; phone: string; address: string; pay: string }) => void;
};

const PAY_OPTIONS = ['货到付款（示例）', '在线支付（示例）', '到店自提（示例）'];

type Errors = Partial<Record<'name' | 'phone' | 'address', string>>;

export default function Checkout({ items, subtotal, shipping, freeShipping, onBack, onShop, onSubmit }: Props) {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [pay, setPay] = useState(PAY_OPTIONS[0]);
  const [errors, setErrors] = useState<Errors>({});

  const total = subtotal + shipping;

  function validate(): Errors {
    const e: Errors = {};
    if (!name.trim()) e.name = '请填写收货人姓名';
    if (!phone.trim()) e.phone = '请填写联系电话';
    else if (!/^[0-9+\-\s]{6,20}$/.test(phone.trim())) e.phone = '电话格式不正确，请填写 6–20 位数字';
    if (!address.trim()) e.address = '请填写收货地址';
    else if (address.trim().length < 6) e.address = '地址太短，请补充楼栋或门牌';
    return e;
  }

  function submit(e: React.FormEvent) {
    e.preventDefault();
    const err = validate();
    setErrors(err);
    if (Object.keys(err).length > 0) return;
    onSubmit({ name: name.trim(), phone: phone.trim(), address: address.trim(), pay });
  }

  if (items.length === 0) {
    return (
      <div className="empty" style={{ marginTop: 60 }}>
        <div className="empty-symbol" aria-hidden="true">🧾</div>
        <h3>购物车为空，暂时无法结算</h3>
        <p>先挑几件商品，再回来填写收货信息。</p>
        <button className="btn-primary" onClick={onShop}>去逛商品</button>
      </div>
    );
  }

  return (
    <section className="checkout" aria-labelledby="co-title">
      <form onSubmit={submit} noValidate>
        <h1 id="co-title">填写收货信息</h1>
        <p className="checkout-sub">演示站点不会上传到服务器，也不会产生真实配送。</p>

        <div className={`field${errors.name ? ' invalid' : ''}`}>
          <label htmlFor="co-name">收货人姓名</label>
          <input
            id="co-name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="例如：李小明"
            autoComplete="name"
            aria-invalid={!!errors.name}
          />
          {errors.name && <p className="field-error">{errors.name}</p>}
        </div>

        <div className={`field${errors.phone ? ' invalid' : ''}`}>
          <label htmlFor="co-phone">联系电话</label>
          <input
            id="co-phone"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            placeholder="例如：13800000000"
            inputMode="tel"
            autoComplete="tel"
            aria-invalid={!!errors.phone}
          />
          {errors.phone && <p className="field-error">{errors.phone}</p>}
        </div>

        <div className={`field${errors.address ? ' invalid' : ''}`}>
          <label htmlFor="co-address">收货地址</label>
          <textarea
            id="co-address"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            placeholder="省 / 市 / 区 街道与门牌号"
            autoComplete="street-address"
            aria-invalid={!!errors.address}
          />
          {errors.address && <p className="field-error">{errors.address}</p>}
        </div>

        <div className="field">
          <span className="pay-label" id="pay-label">支付方式（占位选项）</span>
          <div className="pay-options" role="group" aria-labelledby="pay-label">
            {PAY_OPTIONS.map((p) => (
              <button
                type="button"
                key={p}
                className={`pay-option${pay === p ? ' active' : ''}`}
                onClick={() => setPay(p)}
                aria-pressed={pay === p}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        <div className="checkout-actions">
          <button type="submit" className="btn-primary">提交订单</button>
          <button type="button" className="btn-ghost" onClick={onBack}>返回购物车</button>
        </div>
      </form>

      <aside className="summary-card" aria-label="订单摘要">
        <h2>订单摘要</h2>
        {items.map((l) => (
          <div className="summary-line" key={l.product.id}>
            <span>{l.product.name} <em>× {l.qty}</em></span>
            <span>¥{(l.product.price * l.qty).toFixed(2)}</span>
          </div>
        ))}
        <div className="summary-line" style={{ borderTop: '1px dashed var(--line)', marginTop: 8, paddingTop: 12 }}>
          <span>商品小计</span><span>¥{subtotal.toFixed(2)}</span>
        </div>
        <div className="summary-line">
          <span>运费（满 {freeShipping} 元免）</span>
          <span>{shipping === 0 ? '免运费' : `¥${shipping.toFixed(2)}`}</span>
        </div>
        <div className="summary-total">
          <span>应付合计</span><span>¥{total.toFixed(2)}</span>
        </div>
      </aside>
    </section>
  );
}

